import { writeFile } from "node:fs/promises";
import { build } from "esbuild";

const generatedBanner = `/*
 * Generated from src/ by scripts/build-browser-bundles.js.
 * Do not edit this file directly; update src/ and run npm run build.
 */`;

const bundles = [
  {
    entryPoint: "src/app/overlayApp.js",
    globalName: "StreamJamsOverlay",
    outputPath: "browser/index.js",
  },
  {
    entryPoint: "src/app/setupApp.js",
    globalName: "StreamJamsSetup",
    outputPath: "browser/setup.js",
  },
];

export async function buildBrowserBundles(options = {}) {
  const shouldWrite = options.write ?? false;
  const results = [];

  for (const bundle of bundles) {
    const result = await build({
      entryPoints: [bundle.entryPoint],
      bundle: true,
      write: false,
      format: "iife",
      globalName: bundle.globalName,
      platform: "browser",
      target: ["es2018"],
      banner: {
        js: generatedBanner,
      },
    });
    const contents = result.outputFiles[0].text;
    results.push({ ...bundle, contents });
    if (shouldWrite) {
      await writeFile(new URL(`../${bundle.outputPath}`, import.meta.url), contents);
    }
  }

  return results;
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  await buildBrowserBundles({ write: true });
  console.log("Browser bundles generated from src/.");
}
